/**
 * Builds the fixed styles (plan §3.6): each `src/styles/{slug}.json` in the
 * free plugin becomes a `.mk-style-{slug}` rule in `src/styles/_generated.scss`,
 * which the Modal block's style.scss imports, so the editor and the front end
 * get the same tokens. Runs before `build` and `start`; a unit test fails if
 * the generated file is out of date.
 *
 * The tokens come from src/styles/tokens.js; styles added through the
 * `modal_kit_styles` filter get the same rule from Styles.php at runtime.
 */
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { cssValue, tokens } from '../src/styles/tokens.js';

export { cssValue, tokens };

export const STYLES_DIR = fileURLToPath(
	new URL( '../src/styles/', import.meta.url )
);
export const OUTPUT = join( STYLES_DIR, '_generated.scss' );

/**
 * Every style JSON, sorted by slug.
 *
 * @return {Object[]} Styles.
 */
export function readStyles() {
	return readdirSync( STYLES_DIR )
		.filter( ( file ) => file.endsWith( '.json' ) )
		.sort()
		.map( ( file ) =>
			JSON.parse( readFileSync( join( STYLES_DIR, file ), 'utf8' ) )
		);
}

/**
 * The generated stylesheet.
 *
 * @param {Object[]} styles Styles.
 * @return {string} SCSS.
 */
export function scss( styles ) {
	const rules = styles.map(
		( style ) =>
			`.mk-style-${ style.slug } {\n` +
			tokens( style )
				.map( ( [ name, value ] ) => `\t${ name }: ${ value };\n` )
				.join( '' ) +
			'}\n'
	);

	return (
		'// Generated by bin/build-styles.mjs from src/styles/*.json. Don’t edit:\n' +
		'// change the JSON file, then run `npm run build`.\n\n' +
		rules.join( '\n' )
	);
}

if ( process.argv[ 1 ] === fileURLToPath( import.meta.url ) ) {
	writeFileSync( OUTPUT, scss( readStyles() ) );
}
